const documents = inputData.matches;
const contextChunks = documents.map((doc, idx) => {
  return `[Document ${idx + 1}] (relevance: ${doc.similarity.toFixed(2)})\nSource: ${doc.title} (${doc.category})\nContent: ${doc.content}\n`;
});

const formattedContext = contextChunks.join('\n---\n');
const hasRelevantDocs = documents.length > 0 && documents[0].similarity >= 0.75;

return {
  context: formattedContext,
  document_count: documents.length,
  top_relevance: documents[0]?.similarity || 0,
  has_relevant_docs: hasRelevantDocs,
  source_ids: documents.map(d => d.id)
};

